  FROM redis.zset_0 t LEFT JOIN redis.expiry_0 e ON e.key = t.key WHERE (e.expires_at IS NULL OR e.expires_at > now())
UNION ALL
SELECT 1 AS db, redis.text(t.key) AS key, redis.text(t.member) AS member, t.score, t.member AS member_bytes, t.key AS key_bytes, e.expires_at
