-- Every key once: its type, and its value as jsonb. A string is a JSON string, a hash an
-- object, a list an array, a set an array in insertion order, a sorted set
-- an array of [member, score] by score. Bytes that are not UTF-8 are {"base64": ...}. A
-- stream's entries are not decoded: its value is NULL.
CREATE OR REPLACE VIEW redis.keys AS
SELECT db, key, 'string' AS type, COALESCE(to_jsonb(redis.text(value_bytes)), jsonb_build_object('base64', encode(value_bytes, 'base64'))) AS value, key_bytes, expires_at
  FROM redis.strings
UNION ALL
SELECT db, min(key), 'hash', jsonb_object_agg(COALESCE(field, encode(field_bytes, 'base64')), COALESCE(to_jsonb(redis.text(value_bytes)), jsonb_build_object('base64', encode(value_bytes, 'base64'))) ORDER BY seq),
       key_bytes, min(expires_at)
  FROM redis.hashes GROUP BY db, key_bytes
UNION ALL
SELECT db, min(key), 'list', jsonb_agg(COALESCE(to_jsonb(redis.text(value_bytes)), jsonb_build_object('base64', encode(value_bytes, 'base64'))) ORDER BY position), key_bytes, min(expires_at)
  FROM redis.lists GROUP BY db, key_bytes
UNION ALL
SELECT db, min(key), 'set', jsonb_agg(COALESCE(to_jsonb(redis.text(member_bytes)), jsonb_build_object('base64', encode(member_bytes, 'base64'))) ORDER BY seq), key_bytes, min(expires_at)
  FROM redis.sets GROUP BY db, key_bytes
UNION ALL
SELECT db, min(key), 'zset', jsonb_agg(jsonb_build_array(COALESCE(to_jsonb(redis.text(member_bytes)), jsonb_build_object('base64', encode(member_bytes, 'base64'))), score) ORDER BY score, member_bytes),
       key_bytes, min(expires_at)
  FROM redis.zsets GROUP BY db, key_bytes
UNION ALL
SELECT db, key, 'stream', NULL::jsonb, key_bytes, expires_at
  FROM redis.streams;

-- A memory database's keys, in the shape of redis.keys, from redis.memory_entries: shared
-- memory has no tables to put a view on. A function, so it reads only the database asked
-- for; a whole database is read, in pages.
CREATE OR REPLACE FUNCTION redis.memory_keys(db int)
RETURNS TABLE (db int, key text, type text, value jsonb, key_bytes bytea, expires_at timestamptz)
LANGUAGE sql STABLE AS $$
  SELECT $1, redis.text(m.k), m.t,
         CASE m.t
           WHEN 'string' THEN (array_agg(COALESCE(to_jsonb(redis.text(m.v)), jsonb_build_object('base64', encode(m.v, 'base64')))))[1]
           WHEN 'hash' THEN jsonb_object_agg(COALESCE(redis.text(m.f), encode(m.f, 'base64')), COALESCE(to_jsonb(redis.text(m.v)), jsonb_build_object('base64', encode(m.v, 'base64'))) ORDER BY m.pos)
                                FILTER (WHERE m.t = 'hash')
           WHEN 'zset' THEN jsonb_agg(jsonb_build_array(COALESCE(to_jsonb(redis.text(m.v)), jsonb_build_object('base64', encode(m.v, 'base64'))), convert_from(m.f, 'UTF8')::float8) ORDER BY m.pos)
                                FILTER (WHERE m.t = 'zset')
           WHEN 'stream' THEN NULL
           ELSE jsonb_agg(COALESCE(to_jsonb(redis.text(m.v)), jsonb_build_object('base64', encode(m.v, 'base64'))) ORDER BY m.pos)
         END,
         m.k, to_timestamp(min(d.us) / 1e6)
    FROM redis.memory_entries($1) WITH ORDINALITY AS m(k, t, f, v, pos)
    LEFT JOIN redis.memory_deadlines($1) AS d(k, us) ON d.k = m.k
   GROUP BY m.k, m.t
$$;
